def q(cur, sql):
    cur.execute(sql)
    while cur.description is None:
        if not cur.nextset():
            return [], []
    return [d[0] for d in cur.description], [tuple(r) for r in cur.fetchall()]


def show(cur, label, sql, n=30):
    try:
        cols, rows = q(cur, sql)
        print(f"\n   {label}  ({len(rows)} row(s))")
        print("     " + " | ".join(cols))
        for r in rows[:n]:
            print("     " + " | ".join("" if v is None else str(v) for v in r))
        return cols, rows
    except Exception as e:
        print(f"   !! {label}: {type(e).__name__}: {e}")
        return [], []


def f(v):
    try:
        return float(v)
    except (TypeError, ValueError):
        return None


def main():
    from console.infra.connections import eto_connection
    eto = eto_connection(); cur = eto.cursor()
    try:
        eto.timeout = 300
    except Exception:
        pass
    print(f"console_diag_eto_grids3 — {time.strftime('%Y-%m-%d %H:%M')}  (read-only)")

    print("\n== K1. uspPurchasingItemsToPurchase now vs Peter's 459 rows (exported 8 Oct 2026)")
    t0 = time.time()
    cols, rows = q(cur, "SET NOCOUNT ON; EXEC dbo.uspPurchasingItemsToPurchase")
    print(f"   proc: {len(rows)} rows in {time.time() - t0:.1f}s")
    ix = {c: i for i, c in enumerate(cols)}
    now = {}
    for r in rows:
        k = (int(f(r[ix["ProjectID"]]) or 0), f(r[ix["SpecID"]]), str(r[ix["ItemCompanyID"]]).strip())
        now.setdefault(k, []).append(r)
    same = diff = missing = 0
    diffs, miss = [], []
    for p, m, part, rq, pr, req, act in PETER:
        hits = now.get((p, m, part))
        if not hits:
            missing += 1; miss.append((p, m, part)); continue
        r = hits[0]
        if (f(r[ix["PurchaseQty"]]), f(r[ix["Assigned"]]), f(r[ix["ToPurchase"]])) == (rq, pr, req):
            same += 1
        else:
            diff += 1; diffs.append((p, m, part, (rq, pr, req), (f(r[ix["PurchaseQty"]]), f(r[ix["Assigned"]]), f(r[ix["ToPurchase"]]))))
    print(f"   Peter's rows found with identical Requested/Procured/Required: {same}")
    print(f"   found, quantities changed since 8 Oct: {diff}")
    for d in diffs[:10]:
        print(f"     {d[0]} m{d[1]:g} {d[2]}: then {d[3]} now {d[4]}")
    print(f"   not found now: {missing}")
    keys = set((p, part) for p, m, part in miss)
    onpo = set()
    if keys:
        pids = ",".join(sorted({str(p) for p, _ in keys}))
        _, porows = q(cur, f"""SELECT DISTINCT pod.ProjectID, pod.ItemCompanyID, MAX(poh.PurchaseDate) OVER (PARTITION BY pod.ProjectID, pod.ItemCompanyID)
                               FROM dbo.vwPurchaseOrderDetails pod JOIN dbo.vwPurchaseOrderHeader poh ON poh.PurchaseOrderID = pod.PurchaseOrderID
                               WHERE poh.PurchaseActive = 1 AND pod.ProjectID IN ({pids})""")
        recent = {(int(r[0]), str(r[1]).strip()): r[2] for r in porows}
        for k in keys:
            if k in recent and recent[k] is not None and str(recent[k])[:10] >= "2026-10-08":
                onpo.add(k)
        print(f"     of which the part has an active PO on that project dated 8 Oct 2026 or later: {len(onpo)}")
        rest = [k for k in miss if (k[0], k[2]) not in onpo]
        print(f"     not found and no new PO since 8 Oct: {len(rest)}  e.g. " + ", ".join(f"{p}/m{m:g}/{part}" for p, m, part in rest[:10]))
    newrows = [k for k in now if k not in {(p, m, part) for p, m, part, *_ in PETER}]
    print(f"   rows in the proc now that were not in Peter's export: {len(newrows)}")

    print("\n== K2. Action values and fill of columns that match Peter's grid")
    print("   Action: " + ", ".join(f"{k}={v}" for k, v in Counter(str(r[ix["Action"]]) for r in rows).most_common()))
    for c in ("LastRFQID", "MfgBegin", "RequiredDate", "DeadlineDate", "LastSupplier", "PreferredSupplier",
              "OnOrderQuantity", "OnOrderToInventory", "OnHand", "InvAssigned", "ProcessScheduleID", "ProjectManager", "Engineer"):
        if c in ix:
            n = sum(1 for r in rows if r[ix[c]] not in (None, "", 0, 0.0))
            print(f"   {c:20} non-empty/non-zero {n:>5} of {len(rows)}")

    print("\n== K3. vwPurchasingNonBOM")
    show(cur, "size", """SELECT COUNT(*) AS Rows, COUNT(DISTINCT ProjectID) AS Projects, MIN(DateCreated) AS First, MAX(DateCreated) AS Last,
                                SUM(CASE WHEN Suppressed = 1 THEN 1 ELSE 0 END) AS Suppressed,
                                COUNT(DISTINCT Number) AS DistinctNumbers, SUM(CASE WHEN Number IS NULL OR Number = '' THEN 1 ELSE 0 END) AS NoNumber
                         FROM dbo.vwPurchasingNonBOM""")
    show(cur, "by year created", "SELECT YEAR(DateCreated) AS Yr, COUNT(*) AS Rows FROM dbo.vwPurchasingNonBOM GROUP BY YEAR(DateCreated) ORDER BY 1")
    show(cur, "top AddReason", "SELECT TOP 15 LEFT(ISNULL(AddReason,'(none)'),60) AS AddReason, COUNT(*) AS Rows FROM dbo.vwPurchasingNonBOM GROUP BY LEFT(ISNULL(AddReason,'(none)'),60) ORDER BY 2 DESC")
    show(cur, "top requesters", "SELECT TOP 10 AddedByEmployee, COUNT(*) AS Rows FROM dbo.vwPurchasingNonBOM GROUP BY AddedByEmployee ORDER BY 2 DESC")
    show(cur, "sample rows (newest)", "SELECT TOP 8 NonBOMID, ProjectID, SpecID, ItemCompanyID, PurchaseQty, AddReason, Number, AddedByEmployee, DateCreated FROM dbo.vwPurchasingNonBOM ORDER BY DateCreated DESC")

    print("\n== K4. Non-BOM PO lines (last 2 years) matched to a Non-BOM request")
    show(cur, "match", """
        WITH nb AS (
            SELECT pod.PurchaseDetailID, pod.ProjectID, pod.ItemID
            FROM dbo.vwPurchaseOrderHeader poh JOIN dbo.vwPurchaseOrderDetails pod ON pod.PurchaseOrderID = poh.PurchaseOrderID
            WHERE poh.PurchaseActive = 1 AND poh.PurchaseDate >= DATEADD(year, -2, GETDATE()) AND pod.ItemID IS NOT NULL
              AND NOT EXISTS (SELECT 1 FROM dbo.vwEngBOM b WHERE b.ItemID = pod.ItemID)
              AND NOT EXISTS (SELECT 1 FROM dbo.tblBOMReleaseHistory h WHERE h.ItemID = pod.ItemID))
        SELECT COUNT(*) AS NonBOMLines,
               SUM(CASE WHEN EXISTS (SELECT 1 FROM dbo.vwPurchasingNonBOM n WHERE n.ProjectID = nb.ProjectID AND n.ItemID = nb.ItemID) THEN 1 ELSE 0 END) AS WithRequestSameProject,
               SUM(CASE WHEN EXISTS (SELECT 1 FROM dbo.vwPurchasingNonBOM n WHERE n.ItemID = nb.ItemID) THEN 1 ELSE 0 END) AS WithRequestAnyProject
        FROM nb""")
    show(cur, "all active PO lines, last 2 years, with a Non-BOM request for project + part", """
        SELECT COUNT(*) AS Lines,
               SUM(CASE WHEN EXISTS (SELECT 1 FROM dbo.vwPurchasingNonBOM n WHERE n.ProjectID = pod.ProjectID AND n.ItemID = pod.ItemID) THEN 1 ELSE 0 END) AS WithRequest
        FROM dbo.vwPurchaseOrderHeader poh JOIN dbo.vwPurchaseOrderDetails pod ON pod.PurchaseOrderID = poh.PurchaseOrderID
        WHERE poh.PurchaseActive = 1 AND poh.PurchaseDate >= DATEADD(year, -2, GETDATE())""")

    print("\n== K5. vwPurchasingDemand for 250005 by source")
    show(cur, "demand rows", """
        SELECT CASE WHEN EXISTS (SELECT 1 FROM dbo.vwPurchasingNonBOM n WHERE n.ProjectID = d.ProjectID AND n.SpecID = d.SpecID AND n.ChildID = d.ChildID) THEN 'Non-BOM request'
                    WHEN EXISTS (SELECT 1 FROM dbo.tblBOMReleaseHistory h WHERE h.ProjectID = d.ProjectID AND h.SpecID = d.SpecID AND h.ItemID = d.ChildID) THEN 'Release log'
                    ELSE 'neither' END AS Source,
               COUNT(*) AS Rows, SUM(CAST(d.PurchaseQty AS float)) AS Qty
        FROM dbo.vwPurchasingDemand d WHERE d.ProjectID = 250005
        GROUP BY CASE WHEN EXISTS (SELECT 1 FROM dbo.vwPurchasingNonBOM n WHERE n.ProjectID = d.ProjectID AND n.SpecID = d.SpecID AND n.ChildID = d.ChildID) THEN 'Non-BOM request'
                      WHEN EXISTS (SELECT 1 FROM dbo.tblBOMReleaseHistory h WHERE h.ProjectID = d.ProjectID AND h.SpecID = d.SpecID AND h.ItemID = d.ChildID) THEN 'Release log'
                      ELSE 'neither' END""")
    print("\nDONE — paste everything above.")


if __name__ == "__main__":
    main()
